-- Research page redesign: research areas gain an editable list of focus points
-- (shown under each stream on the Research page), the missing Patient & community
-- engagement image is replaced, and the Research page gets a new layout styled by
-- the pr-* classes in app/builder.css. The previous layout is kept as a page
-- revision. Guarded on node ids so an edited page layout is left alone.

ALTER TABLE public.research_areas ADD COLUMN IF NOT EXISTS focus_points text[] NOT NULL DEFAULT '{}';

UPDATE public.research_areas SET focus_points = ARRAY['Non-urgent interfacility patient transfers', 'Rural and remote service delivery', 'Coordinated, integrated care pathways', 'Patient and caregiver experiences of care'] WHERE id = 'e36490db-0e18-40ad-956e-24f7ac59a6bb' AND focus_points = '{}';
UPDATE public.research_areas SET focus_points = ARRAY['Immigrant, refugee, and newcomer health', 'Rural health equity', 'Social determinants of health', 'Decolonizing healthcare and research'] WHERE id = '8d215b66-dddd-44d5-a874-3d5a9b553cc3' AND focus_points = '{}';
UPDATE public.research_areas SET focus_points = ARRAY['Farm-level food waste and redistribution', 'Household and community food security', 'Food security among newcomers', 'Resilient local and regional food systems'] WHERE id = '81f0a2fd-aa02-4d85-8862-69ea75bede23' AND focus_points = '{}';
UPDATE public.research_areas SET focus_points = ARRAY['Community-based participatory research', 'Patient and caregiver partnership', 'Lived-experience advisory roles', 'Sharing findings back with communities'] WHERE id = '5eccd0bc-5d00-4fec-b14b-f2a29d3f9893' AND focus_points = '{}';
UPDATE public.research_areas SET focus_points = ARRAY['Policy briefs and knowledge mobilization', 'Implementation science', 'Program and service evaluation', 'Partnerships with decision-makers'] WHERE id = 'cdb6c65e-ba5a-4c89-8e57-f6bace86a889' AND focus_points = '{}';

-- seed/patient-community-engagement.png was never uploaded (404).
UPDATE public.research_areas
SET image_url = 'https://376vyh7j.us-east.insforge.app/api/storage/buckets/site-images/objects/pexels-elina-sazonova-2705756-1793406263155-dtsv41.webp?v=1d638e2a119a1d9031bfad653036d3c7',
    image_key = 'pexels-elina-sazonova-2705756-1793406263155-dtsv41.webp'
WHERE id = '5eccd0bc-5d00-4fec-b14b-f2a29d3f9893' AND image_key = 'seed/patient-community-engagement.png';

INSERT INTO public.cms_page_revisions (page_id, title, content, seo, reason)
SELECT id, title || ' (before redesign)', published_content, seo, 'publish'
FROM public.cms_pages
WHERE slug = 'research' AND jsonb_array_length(published_content->'sections') = 2
  AND published_content->'sections'->0->>'id' = 'xvkw8uq41'
  AND published_content->'sections'->1->>'id' = 'xcgllhu80';

